DROP TABLE IF EXISTS `complaints`;
CREATE TABLE `complaints` (
  `id` int NOT NULL AUTO_INCREMENT,
  `complaint_id` varchar(30) NOT NULL,
  `citizen_id` int NOT NULL,
  `category` enum('Garbage & Waste','Roads & Potholes','Streetlights','Water Supply','Sewerage','Waterlogging & Drainage') NOT NULL,
  `description` text NOT NULL,
  `image_path` varchar(255) NOT NULL,
  `location` varchar(255) NOT NULL,
  `status` enum('Submitted','Assigned','In Progress','Resolved','Rejected') DEFAULT 'Submitted',
  `department` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `resolution_proof` varchar(255) DEFAULT NULL,
  `resolution_notes` text,
  `proof_status` enum('Pending','Verified','Rejected') DEFAULT 'Pending',
  `latitude` decimal(10,7) DEFAULT NULL,
  `longitude` decimal(10,7) DEFAULT NULL,
  `selected_department` varchar(100) DEFAULT NULL,
  `ai_department` varchar(100) DEFAULT NULL,
  `ai_department_confidence` decimal(5,2) DEFAULT NULL,
  `ai_priority_score` decimal(6,2) DEFAULT NULL,
  `ai_priority` varchar(20) DEFAULT NULL,
  `ai_verification_score` decimal(6,2) DEFAULT NULL,
  `ai_verification_status` varchar(30) DEFAULT NULL,
  `ai_reason` text,
  `assignment_source` varchar(20) NOT NULL DEFAULT 'Manual',
  `admin_feedback` text,
  `ai_suggested_solution` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `complaint_id` (`complaint_id`),
  KEY `citizen_id` (`citizen_id`),
  CONSTRAINT `complaints_ibfk_1` FOREIGN KEY (`citizen_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

